package dev.reliefgrid;
import dev.reliefgrid.engine.AllocationEngine;import dev.reliefgrid.model.Category;import org.junit.jupiter.api.Test;import java.util.*;import static org.junit.jupiter.api.Assertions.*;
class SimulationBenchmarkTest {
 @Test void fixedFiveShelterTwentyRequestTenVolunteerScenario(){Random rnd=new Random(317);List<AllocationEngine.Place> places=new ArrayList<>();for(int i=1;i<=5;i++)places.add(new AllocationEngine.Place(i,16.49+i*.012,80.60+i*.014,i%2==0));List<AllocationEngine.Stock> stocks=new ArrayList<>();long id=1;for(var p:places)for(Category c:Category.values())stocks.add(new AllocationEngine.Stock(id++,p.id(),c,4+rnd.nextInt(8)));List<AllocationEngine.Demand> demands=new ArrayList<>();for(int i=0;i<20;i++)demands.add(new AllocationEngine.Demand(i+1,1+i%5,Category.values()[i%4],4+rnd.nextInt(8),1+rnd.nextInt(5),i));List<AllocationEngine.Carrier> carriers=new ArrayList<>();for(int i=0;i<10;i++)carriers.add(new AllocationEngine.Carrier(i+1,1+i%5,7+rnd.nextInt(8),true));var in=new AllocationEngine.Input(places,stocks,demands,carriers);for(var result:List.of(AllocationEngine.baseline(in),AllocationEngine.optimized(in))){assertTrue(result.allocated()>0);assertTrue(result.allocated()<=carriers.stream().mapToInt(AllocationEngine.Carrier::capacity).sum());System.out.printf("%s: allocated=%d distanceKmUnits=%.2f computeMs=%.3f%n",result==null?"none":result.picks().get(0).explanation().startsWith("FCFS")?"FCFS":"OPT",result.allocated(),result.distance(),result.nanos()/1e6);}}
}
